-- === entry 321: enable ===

UPDATE achievements SET enabled = 1 WHERE id IN (11000004,11000006,11000007,11000008,11000009,11000011,11000012,11000013,11000014,11000015,11000019,11000020,11000021,11000025,11000027,11000028,11000029,11000031,11000032,11000033,11000034,11000035,11000036,11000037,11000039,11000040,11000042,11000043,11000044,11000045,11000046,11000047,11000048,11000049,11000050,11000051,11000054,11000055,11000056,11000060,11000061,11000062,11000063,11000064,11000065,11000066,11000067,11000068,11000069,11000070,11000071,11000072,11000073,11000074,11000075,11000076,11000077,11000078,11000079,11000080,11000081,11000082,11000083,11000084,11000085,11000086,11000087,11000088,11000089,11000090,11000091,11000092,11000093,11000094,11000095,11000097,11000098,11000100,11000101,11000102,11000103,11000104,11000105,11000106,11000107,11000108,11000109,11000110,11000111,11000112,11000113,11000114,11000116,11000117,11000118,11000119,11000120,11000121,11000122,11000123,11000127,11000128,11000130,11000131,11000132,11000133,11000134,11000135,11000136,11000137,11000138,11000139,11000140,11000142,11000143,11000144,11000145,11000146,11000147,11000148,11000149,11000150,11000151,11000152,11000153,11000154,11000156,11000157,11000158,11000159,11000160,11000161,11000162,11000163,11000164,11000165,11000166,11000167,11000168,11000169,11000170,11000175);;

