-- === entry 330: canaries ===
-- fail-closed canaries: any violation inserts a PK-colliding row so the boot runner fails loudly
SELECT 9508300, 'ASSERTION FAILED: enabled slayer def without criteria', 1 FROM DUAL WHERE EXISTS (
SELECT 1 FROM achievements a WHERE a.enabled=1 AND a.id BETWEEN 11000000 AND 11099999 AND NOT EXISTS (SELECT 1 FROM achievement_criteria c WHERE c.achievement_id=a.id)
) LIMIT 1;

SELECT 9508300, 'ASSERTION FAILED: slayer criteria attached to a disabled def', 1 FROM DUAL WHERE EXISTS (
SELECT 1 FROM achievement_criteria cr JOIN achievements a ON a.id=cr.achievement_id WHERE cr.id BETWEEN 7001000 AND 7001805 AND a.enabled=0
) LIMIT 1;

SELECT 9508300, 'ASSERTION FAILED: slayer criterion with unusable race target', 1 FROM DUAL WHERE EXISTS (
SELECT 1 FROM achievement_criteria WHERE id BETWEEN 7001000 AND 7001805 AND (target_id = 0 OR target_id > 9999)
) LIMIT 1;

SELECT 9508300, 'ASSERTION FAILED: slayer criterion without component', 1 FROM DUAL WHERE EXISTS (
SELECT 1 FROM achievement_criteria cr WHERE cr.id BETWEEN 7001000 AND 7001805 AND NOT EXISTS (SELECT 1 FROM achievement_components cp WHERE cp.achievement_id=cr.achievement_id AND cp.component_type=cr.component_type AND cp.component_id=cr.component_id)
) LIMIT 1;

SELECT 9508300, 'ASSERTION FAILED: slayer reward set without option entries', 1 FROM DUAL WHERE EXISTS (
SELECT 1 FROM reward_sets s WHERE s.reward_set_id BETWEEN 9508300 AND 9508441 AND NOT EXISTS (SELECT 1 FROM reward_option_entries e WHERE e.reward_set_id=s.reward_set_id)
) LIMIT 1;

SELECT 9508300, 'ASSERTION FAILED: slayer reward entry pointing at a missing reward', 1 FROM DUAL WHERE EXISTS (
SELECT 1 FROM reward_option_entries e WHERE e.reward_set_id BETWEEN 9508300 AND 9508441 AND NOT EXISTS (SELECT 1 FROM rewards r WHERE r.reward_id=e.reward_id)
) LIMIT 1;

SELECT 9508300, 'ASSERTION FAILED: slayer title reward referencing an NMS-band title_set', 1 FROM DUAL WHERE EXISTS (
SELECT 1 FROM rewards r WHERE r.reward_type=5 AND r.reward_data_id BETWEEN 10001 AND 11095 AND r.reward_id BETWEEN 9541000 AND 9541411
) LIMIT 1;

SELECT 9508300, 'ASSERTION FAILED: slayer reward_sources cardinality wrong', 1 FROM DUAL WHERE EXISTS (
SELECT 1 FROM DUAL HAVING (SELECT COUNT(*) FROM reward_sources WHERE source_type=1 AND source_id BETWEEN 11000000 AND 11099999) <> 142
) LIMIT 1;
